package com.hbm.machine.reactor.iter.breeder;
import com.hbm.api.computer.*;
import com.hbm.energy.NodeConnection;
import com.hbm.fluid.*;
import com.hbm.fluid.network.*;
import com.hbm.fusion.plasma.*;
import com.hbm.item.fluid.FluidIdentifier;
import com.hbm.item.meteoritesword.MeteoriteSwordContent;
import com.hbm.machine.foundry.crucible.ThermalMachine;
import com.hbm.machine.reactor.rbmk.irradiation.RbmkIrradiationRecipes;
import com.hbm.multiblock.DummyableBlock;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.entity.player.*;
import net.minecraft.world.inventory.AbstractContainerMenu;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.state.BlockState;
/** Actual fusion neutron breeder, shared19-source solid table plus3fluid irradiation and original secret sword path. */
public final class FusionBreederEntity extends ThermalMachine implements StandardFluidTransceiver,FusionPowerReceiver,ComputerControl {
 public static final double CAPACITY=10000D;public final FluidTank[] tanks={new FluidTank(HbmFluids.NONE,16000),new FluidTank(HbmFluids.NONE,16000)};public double neutronEnergy,neutronEnergySync,progress;public boolean muffled,tilted;private PlasmaNode plasmaNode;private FluidPorts fluidPorts;
 public FusionBreederEntity(BlockPos pos,BlockState state){super(FusionBreederContent.ENTITY.get(),pos,state,3);}
 @Override protected String title(){return "container.fusionBreeder";}@Override public AbstractContainerMenu createMenu(int id,Inventory inventory,Player player){return new FusionBreederMenu(id,inventory,this,worldPosition);}
 public static NodeConnection[] portConnections(BlockPos core,Direction dir){var side=dir.getClockWise();var points=new BlockPos[]{core.relative(dir,2).above(2),core.relative(side),core.relative(side,-1),core.relative(dir).relative(side),core.relative(dir).relative(side,-1)};var faces=new Direction[]{dir,side,side.getOpposite(),side,side.getOpposite()};var out=new NodeConnection[5];for(int i=0;i<5;i++)out[i]=new NodeConnection(points[i].relative(faces[i]),faces[i]);return out;}
 public static void tick(Level level,BlockPos pos,BlockState state,FusionBreederEntity machine){if(!(level instanceof ServerLevel server))return;var connections=portConnections(pos,DummyableBlock.facing(state));if(machine.fluidPorts==null)machine.fluidPorts=new FluidPorts(Arrays.stream(connections).map(NodeConnection::origin).toArray(BlockPos[]::new),connections);machine.fluidPorts.update(server,machine);machine.tanks[0].setType(0,machine.slots.toArray(ItemStack[]::new));if(!machine.canProcessSolid()&&!machine.canProcessLiquid())machine.progress=0;machine.neutronEnergySync=machine.neutronEnergy;var dir=DummyableBlock.facing(state).getOpposite();var space=PlasmaNetworks.nodespace(server);if(machine.plasmaNode==null||machine.plasmaNode.isExpired()){var origin=pos.relative(dir,2).above(2);machine.plasmaNode=space.getNode(origin);if(machine.plasmaNode==null){machine.plasmaNode=new PlasmaNode(origin).setConnections(new NodeConnection(origin.relative(dir),dir));space.createNode(machine.plasmaNode);}}if(machine.plasmaNode.hasValidNet())machine.plasmaNode.addReceiver(machine);machine.sync(25);machine.neutronEnergy=0;}
 public boolean canProcessSolid(){var input=slots.get(1);if(input.isEmpty())return false;if(input.is(MeteoriteSwordContent.IRRADIATED.get())&&slots.get(2).isEmpty())return true;var recipe=RbmkIrradiationRecipes.find(level.getRecipeManager(),input);if(recipe==null)return false;if(recipe.gas().isPresent()){var fluid=recipe.gas().get();if(tanks[1].getTankType()!=fluid.type&&tanks[1].getFill()>0)return false;tanks[1].setTankType(fluid.type);if(tanks[1].getFill()+fluid.fill>tanks[1].getMaxFill())return false;}var out=recipe.solid();var current=slots.get(2);return current.isEmpty()||out.isEmpty()||current.getItem()==out.getItem()&&metadata(current)==metadata(out)&&current.getCount()+out.getCount()<=current.getMaxStackSize();}
 public boolean canProcessLiquid(){var recipe=FluidBreedingRecipes.find(level.getRecipeManager(),tanks[0].getTankType());if(recipe==null||tanks[0].getFill()<recipe.input().fill)return false;var fluid=recipe.output();if(tanks[1].getTankType()!=fluid.type&&tanks[1].getFill()>0)return false;tanks[1].setTankType(fluid.type);return tanks[1].getFill()+fluid.fill<=tanks[1].getMaxFill();}
 public void doProgress(){if(canProcessSolid()){progress+=neutronEnergy;if(progress>CAPACITY){if(slots.get(1).is(MeteoriteSwordContent.IRRADIATED.get())){removeItem(1,1);slots.set(2,new ItemStack(MeteoriteSwordContent.FUSED.get()));}else{var recipe=RbmkIrradiationRecipes.find(level.getRecipeManager(),slots.get(1));removeItem(1,1);recipe.gas().ifPresent(gas->tanks[1].setFill(tanks[1].getFill()+gas.fill));if(!recipe.solid().isEmpty()){if(slots.get(2).isEmpty())slots.set(2,recipe.solid().copy());else slots.get(2).grow(recipe.solid().getCount());}}progress=0;setChanged();}}else if(canProcessLiquid()){progress+=neutronEnergy;if(progress>CAPACITY){var recipe=FluidBreedingRecipes.find(level.getRecipeManager(),tanks[0].getTankType());tanks[0].setFill(tanks[0].getFill()-recipe.input().fill);tanks[1].setFill(tanks[1].getFill()+recipe.output().fill);progress=0;setChanged();}}else progress=0;}
 private static int metadata(ItemStack stack){return stack.getOrDefault(com.hbm.hazard.HbmHazards.LEGACY_METADATA.get(),stack.getDamageValue());}
 @Override public boolean receivesFusionPower(){return false;}@Override public void receiveFusionPower(long power,double neutronPower,float r,float g,float b){neutronEnergy=neutronPower;doProgress();}
 @Override public int[] getSlotsForFace(Direction side){return new int[]{1,2};}@Override public boolean canPlaceItem(int slot,ItemStack stack){return slot==0?stack.getItem() instanceof FluidIdentifier:slot==1&&level!=null&&RbmkIrradiationRecipes.find(level.getRecipeManager(),stack)!=null;}@Override public boolean canTakeItemThroughFace(int slot,ItemStack stack,Direction side){return slot==2;}
 @Override public FluidTank[] getAllTanks(){return tanks;}@Override public FluidTank[] getReceivingTanks(){return new FluidTank[]{tanks[0]};}@Override public FluidTank[] getSendingTanks(){return new FluidTank[]{tanks[1]};}@Override public List<TankView> tanks(){return Arrays.stream(tanks).map(t->new TankView(t.getTankType(),t.getFill(),t.getMaxFill())).toList();}@Override public List<ProgressView> progressBars(){return List.of(new ProgressView("jade.hbm.fusion_breeder.progress",progress,CAPACITY,0xa00000));}
 @Override protected void saveMachine(CompoundTag tag){tag.putDouble("progress",progress);for(int i=0;i<2;i++)tanks[i].writeToNBT(tag,"t"+i);tag.putBoolean("muffled",muffled);tag.putBoolean("tilted",tilted);}@Override protected void loadMachine(CompoundTag tag){progress=tag.getDouble("progress");for(int i=0;i<2;i++)tanks[i].readFromNBT(tag,"t"+i);muffled=tag.getBoolean("muffled");tilted=tag.getBoolean("tilted");}
 @Override public CompoundTag getUpdateTag(HolderLookup.Provider lookup){var tag=super.getUpdateTag(lookup);tag.putDouble("neutronEnergy",neutronEnergySync);return tag;}@Override public void handleUpdateTag(CompoundTag tag,HolderLookup.Provider lookup){super.handleUpdateTag(tag,lookup);neutronEnergy=tag.getDouble("neutronEnergy");neutronEnergySync=neutronEnergy;}
 private void disconnect(){if(level instanceof ServerLevel server){if(fluidPorts!=null)fluidPorts.remove(server);if(plasmaNode!=null)PlasmaNetworks.nodespace(server).destroyNode(plasmaNode);}fluidPorts=null;plasmaNode=null;}@Override public void setRemoved(){disconnect();super.setRemoved();}@Override public void onChunkUnloaded(){disconnect();super.onChunkUnloaded();}
 private Object[] fluidInfo(){return new Object[]{tanks[0].getFill(),tanks[0].getMaxFill(),tanks[0].getTankType().getUnlocalizedName(),tanks[1].getFill(),tanks[1].getMaxFill(),tanks[1].getTankType().getUnlocalizedName()};}private Object[] craftingInfo(){var in=slots.get(1);var out=slots.get(2);return new Object[]{in.isEmpty()?"":in.getDescriptionId(),in.getCount(),out.isEmpty()?"":out.getDescriptionId(),out.getCount()};}
 @Override public String computerType(){return "ntm_fusion_breeder";}@Override public String[] computerMethods(){return new String[]{"getNeutronEnergy","getProgress","getFluid","getCrafting","getInfo"};}@Override public Object[] callComputer(String method,ComputerArguments args){return switch(method){case "getNeutronEnergy"->new Object[]{neutronEnergySync};case "getProgress"->new Object[]{progress/CAPACITY};case "getFluid"->fluidInfo();case "getCrafting"->craftingInfo();case "getInfo"->{var result=new ArrayList<Object>();result.add(neutronEnergySync);result.add(progress/CAPACITY);result.addAll(Arrays.asList(fluidInfo()));result.addAll(Arrays.asList(craftingInfo()));yield result.toArray();}default->throw new ComputerException("No such method: "+method);};}
 @Override public boolean isMuffled(){return muffled;}@Override public void setMuffled(boolean value){muffled=value;}
}
